import re


def eval_expression(expr):
    """
    算術式を計算する。

    対応する演算子:
        +, -, *, /
    対応する記法:
        括弧、正負の符号、小数

    例:
        eval_expression("3 + 4 * (2 - 1)")  # 7
        eval_expression("-2 * 3")           # -6
    """

    token_pattern = re.compile(
        r"\s*(?:(\d+(?:\.\d*)?|\.\d+)|([()+\-*/]))"
    )

    tokens = []
    position = 0

    while position < len(expr):
        match = token_pattern.match(expr, position)

        if not match:
            raise ValueError(
                f"不正な文字があります: {expr[position]!r}"
            )

        number, operator = match.groups()

        if number is not None:
            if "." in number:
                tokens.append(float(number))
            else:
                tokens.append(int(number))
        else:
            tokens.append(operator)

        position = match.end()

    if not tokens:
        raise ValueError("式が空です")

    index = 0

    def current_token():
        return tokens[index] if index < len(tokens) else None

    def parse_expression():
        """加算・減算"""
        nonlocal index

        value = parse_term()

        while current_token() in ("+", "-"):
            operator = current_token()
            index += 1
            right = parse_term()

            if operator == "+":
                value += right
            else:
                value -= right

        return value

    def parse_term():
        """乗算・除算"""
        nonlocal index

        value = parse_factor()

        while current_token() in ("*", "/"):
            operator = current_token()
            index += 1
            right = parse_factor()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    def parse_factor():
        """数値、括弧、単項の正負"""
        nonlocal index

        token = current_token()

        if token == "+":
            index += 1
            return parse_factor()

        if token == "-":
            index += 1
            return -parse_factor()

        if token == "(":
            index += 1
            value = parse_expression()

            if current_token() != ")":
                raise ValueError("閉じ括弧 ')' がありません")

            index += 1
            return value

        if isinstance(token, (int, float)):
            index += 1
            return token

        raise ValueError(f"予期しないトークン: {token!r}")

    result = parse_expression()

    if index != len(tokens):
        raise ValueError(f"予期しないトークン: {current_token()!r}")

    return result
